function sqlLit(v){ if(v===null) return "NULL"; if(typeof v==="number") return String(v); return "'"+String(v).replace(/'/g,"''")+"'"; }
const SEED_SQL = "CREATE TABLE films (id INTEGER PRIMARY KEY, title TEXT, release_year INTEGER, country TEXT, duration INTEGER, language TEXT, certification TEXT, gross INTEGER, budget INTEGER);\n" +
  FILMS.map((f,i)=>"INSERT INTO films VALUES ("+[i+1].concat(f).map(sqlLit).join(", ")+");").join("\n");
